WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY ends_on DESC, id) AS rank_in_group FROM promotions QUALIFY rank_in_group = 1) SELECT CASE WHEN discount_pct >= 0.3 THEN 'HIGH' ELSE 'LOW' END AS discount_pct_tier, DATE_TRUNC('QUARTER', ends_on) AS quarter_start, STDDEV_SAMP(discount_pct) AS discount_pct_stddev, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, MIN(discount_pct) AS min_discount_pct FROM ranked GROUP BY GROUPING SETS ((CASE WHEN discount_pct >= 0.3 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('QUARTER', ends_on)), (CASE WHEN discount_pct >= 0.3 THEN 'HIGH' ELSE 'LOW' END))
